      "path": "package.json",
      "content": "{\n  \"name\": \"@a9i5k4/dsh-anchored-monitor\",\n  \"version\": \"0.3.1\",\n  \"description\": \"DSH 实时思维链锚定监控插件: we/let's/let me 指纹波段检测(spec/mixed/react) + L1温和引导/L2强制重置/L3会话重启分级干预; 左侧栏入口 + 液体毛玻璃浮层 + 变阻器式思考强度条; 独立监控进程 + JSONL 实验日志 + 离线回放/参数校准; 变阻器条可选严肃/「滑动变祖器」梗双皮肤。\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=22.19\"\n  },\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"bin\": {\n    \"anchored-monitor\": \"dist/monitor/index.js\"\n  },\n  \"files\": [\n    \"lib\",\n    \"dist\",\n    \"config\",\n    \"preset\",\n    \"web\",\n    \"assets\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"plugin\",\n    \"anchored\",\n    \"monitor\",\n    \"reasoning\",\n    \"chain-of-thought\",\n    \"spec-band\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Aik358/dsh-anchored-monitor.git\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json && node scripts/assemble-client.mjs\",\n    \"client:bundle\": \"node scripts/assemble-client.mjs\",\n    \"start\": \"node dist/monitor/index.js\",\n    \"dev\": \"node dist/monitor/index.js\",\n    \"demo:generate\": \"node dist/demo/generate.js\",\n    \"demo:feed\": \"node dist/demo/feed.js\",\n    \"replay\": \"node dist/scripts/replay.js\",\n    \"calibrate\": \"node dist/scripts/calibrate.js\",\n    \"preview:build\": \"node dist/scripts/build-preview.js\"\n  },\n  \"dependencies\": {\n    \"ajv\": \"^8.20.0\",\n    \"yaml\": \"^2.9.0\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^24.10.0\",\n    \"typescript\": \"^5.9.3\"\n  }\n}\n"
