      "path": "src/shared/config-loader.ts",
      "content": "/**\n * 配置加载与 JSON Schema 校验 + 深合并(支持 profile 叠加与 CLI 覆盖)\n */\n\nimport { readFile } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport { Ajv } from 'ajv'\nimport { parse as parseYaml } from 'yaml'\nimport type { MonitorConfig } from './types.js'\nimport { configHash, resolveFromRoot } from './paths.js'\n\nexport interface ConfigLoadOptions {\n  root: string\n  /** 主配置文件路径(绝对或相对项目根); 缺省 config/default.yaml */\n  configPath?: string\n  /** profile 名(不带 .yaml), 位于 config/ 下, 深合并到主配置之上 */\n  profile?: string\n  /** 运行时覆盖(如 --port), 优先级最高 */\n  overrides?: Record<string, unknown>\n}\n\nexport interface LoadedConfig {\n  config: MonitorConfig\n  hash: string\n  profileName: string\n  sources: string[]\n}\n\nfunction isPlainObject(v: unknown): v is Record<string, unknown> {\n  return typeof v === 'object' && v !== null && !Array.isArray(v)\n}\n\n/** 深合并: 对象递归合并, 数组整体替换 */\nexport function deepMerge<T>(base: T, patch: unknown): T {\n  if (!isPlainObject(base) || !isPlainObject(patch)) {\n    return (patch === undefined ? base : patch) as T\n  }\n  const out: Record<string, unknown> = { ...(base as Record<string, unknown>) }\n  for (const [k, v] of Object.entries(patch)) {\n    out[k] = isPlainObject(v) && isPlainObject(out[k]) ? deepMerge(out[k], v) : v\n  }\n  return out as T\n}\n\nexport async function loadConfig(opts: ConfigLoadOptions): Promise<LoadedConfig> {\n  const schemaRaw = await readFile(join(opts.root, 'config', 'schema.json'), 'utf8')\n  const schema = JSON.parse(schemaRaw) as Record<string, unknown>\n\n  const cfgPath = opts.configPath\n    ? resolveFromRoot(opts.root, opts.configPath)\n    : join(opts.root, 'config', 'default.yaml')\n  const sources: string[] = [cfgPath]\n\n  const baseRaw = await readFile(cfgPath, 'utf8')\n  let config = parseYaml(baseRaw) as Record<string, unknown>\n  let profileName = 'default'\n\n  if (opts.profile) {\n    profileName = opts.profile.replace(/\\.yaml$/i, '')\n    // 'default' 就是主配置本身(不传 --profile 也是它), 跳过重复合并, 幂等\n    if (profileName !== 'default') {\n      const profPath = join(opts.root, 'config', profileName + '.yaml')\n      const profRaw = await readFile(profPath, 'utf8')\n      config = deepMerge(config, parseYaml(profRaw))\n      sources.push(profPath)\n    }\n  }\n  if (opts.overrides) config = deepMerge(config, opts.overrides)\n\n  const ajv = new Ajv({ allErrors: true, strict: false })\n  const validate = ajv.compile(schema)\n  if (!validate(config)) {\n    const msgs = (validate.errors ?? [])\n      .map((e) => `${e.instancePath || '/'} ${e.message ?? 'invalid'}`)\n      .join('; ')\n    throw new Error(`配置校验失败(${sources.join(', ')}): ${msgs}`)\n  }\n\n  const monitorConfig = config as unknown as MonitorConfig\n  return { config: monitorConfig, hash: configHash(monitorConfig), profileName, sources }\n}\n"
    },
    {
      "path": "src/monitor/session-manager.ts",
      "content": "/**\n * SessionManager — 每会话监控流水线核心:\n * 特征提取 → 窗口聚合 → 评分 → 基线/趋势/异常 → 决策状态机 → 信号发送\n * 所有可调参数来自 MonitorConfig, 无硬编码策略\n */\n\nimport type {\n  Band,\n  InterventionLevel,\n  InterventionSignal,\n  MonitorConfig,\n  MonitorEvent,\n  Phase,\n  ReasoningBlock,\n  SessionSnapshot,\n  TextChunkBlock,\n  SessionSummary,\n  TrendDirection,\n  WindowSnapshot\n} from '../shared/types.js'\nimport { FeatureExtractor } from './feature/extractor.js'\nimport type { CompiledLexicon } from './feature/lexicon.js'\nimport { SlidingWindow } from './window/sliding-window.js'\nimport { DecayWindow } from './window/decay-window.js'\nimport type { WindowAggregator } from './window/sliding-window.js'\nimport { createScoring, type ScoringStrategy } from './scoring/index.js'\nimport { BaselineCalculator } from './trend/baseline.js'\nimport { checkAnomalies, computeTrend, isRecovered } from './trend/anomaly.js'\nimport { CooldownManager } from './intervention/cooldown.js'\nimport { decideIntervention } from './intervention/decision.js'\nimport { SignalSender } from './intervention/signal-sender.js'\n\nconst MAX_HISTORY_POINTS = 5000\nconst MAX_NORMALIZED_HISTORY = 400\n\ninterface HistoryPoint {\n  sequence: number\n  timestamp: number\n  score: number\n  normalizedScore: number\n  band: Band\n  trend: TrendDirection\n  phase: Phase\n  ratio: number | null\n  confidence: number\n  percentile: number | null\n  windowAggregate: { positive: number; negative: number; neutral: number }\n}\n\ninterface InterventionRecord {\n  level: Exclude<InterventionLevel, 'none'>\n  reason: string\n  timestamp: number\n  sequence: number\n  status: 'sent' | 'acked'\n  ackedAt?: number\n  payload: InterventionSignal['payload']\n}\n\ninterface SessionState {\n  sessionId: string\n  workspace?: string\n  title?: string\n  source: 'log_tail' | 'ipc_push'\n  startedAt: number\n  lastActivityAt: number\n  lastReasoningAt: number\n  blockCount: number\n  lastSequence: number\n  textSeq: number\n  textChars: number\n  textChunks: number\n  lastTextAt: number\n  textSample: string\n  textTimes: { at: number; chars: number }[]\n  guardLastAt: { stall: number; leak: number }\n  cotAlerts: { stall: number; leak: number }\n  lastAlertAt: number | null\n  phase: Phase\n  l2Attempts: number\n  window: WindowAggregator\n  baseline: BaselineCalculator\n  rawHistory: number[]\n  normalizedHistory: number[]\n  history: HistoryPoint[]\n  cooldowns: CooldownManager\n  interventions: InterventionRecord[]\n  lastNormalized: number | null\n  ended: boolean\n}\n\nexport interface SessionManagerOptions {\n  config: MonitorConfig\n  configHash: string\n  lexicon: CompiledLexicon\n  extractor: FeatureExtractor\n  scoring: ScoringStrategy\n  emit: (event: MonitorEvent) => void\n  sender: SignalSender\n}\n\n/** persona_ratio = 窗口内 \"let me\" 词数 / (正向词数 + \"let me\" 词数), 见 router-core.bandOf */\nexport function personaRatio(snap: WindowSnapshot, lexicon: CompiledLexicon): number | null {\n  let pos = 0\n  let neg = 0\n  for (const t of lexicon.positiveTerms) pos += snap.features[t] ?? 0\n  for (const t of lexicon.negativeTerms) neg += snap.features[t] ?? 0\n  const total = pos + neg\n  return total > 0 ? neg / total : null\n}\n\nexport class SessionManager {\n  private sessions = new Map<string, SessionState>()\n  private interventionsEnabled: boolean\n\n  constructor(private readonly opts: SessionManagerOptions) {\n    this.interventionsEnabled = opts.config.intervention.enabled !== false\n  }\n\n  /** 运行时切换干预总开关(关闭=只监控不干预, 不丢会话状态) */\n  setInterventionsEnabled(enabled: boolean): void {\n    if (this.interventionsEnabled === enabled) return\n    this.interventionsEnabled = enabled\n    this.opts.emit({ type: 'intervention_toggle', timestamp: Date.now(), enabled })\n    if (!enabled) {\n      // 关闭干预时, 挂起状态回到健康(不再累积 critical 升级)\n      for (const state of this.sessions.values()) {\n        if (state.phase !== 'restart') state.phase = 'healthy'\n      }\n    }\n  }\n\n  isInterventionsEnabled(): boolean {\n    return this.interventionsEnabled\n  }\n\n  private bandOf(ratio: number | null, baseline: BaselineCalculator): Band {\n    if (ratio === null || baseline.mean === null) return 'unknown'\n    if (ratio < this.opts.config.bands.spec_max) return 'spec'\n    if (ratio < this.opts.config.bands.react_min) return 'mixed'\n    return 'react'\n  }\n\n  private getOrCreate(sessionId: string, source: 'log_tail' | 'ipc_push'): SessionState {\n    const existing = this.sessions.get(sessionId)\n    if (existing) return existing\n    const cfg = this.opts.config\n    const state: SessionState = {\n      sessionId,\n      source,\n      startedAt: Date.now(),\n      lastActivityAt: Date.now(),\n      lastReasoningAt: Date.now(),\n      blockCount: 0,\n      lastSequence: 0,\n      textSeq: 0,\n      textChars: 0,\n      textChunks: 0,\n      lastTextAt: 0,\n      textSample: '',\n      textTimes: [],\n      guardLastAt: { stall: 0, leak: 0 },\n      cotAlerts: { stall: 0, leak: 0 },\n      lastAlertAt: null,\n      phase: 'healthy',\n      l2Attempts: 0,\n      window:\n        cfg.window.type === 'decay'\n          ? new DecayWindow(cfg.window.decay_lambda)\n          : new SlidingWindow(cfg.window.size),\n      baseline: new BaselineCalculator(cfg.threshold.baseline_window, cfg.threshold.baseline_min_samples),\n      rawHistory: [],\n      normalizedHistory: [],\n      history: [],\n      cooldowns: new CooldownManager(cfg.intervention.cooldowns),\n      interventions: [],\n      lastNormalized: null,\n      ended: false\n    }\n    this.sessions.set(sessionId, state)\n    this.opts.emit({\n      type: 'session_start',\n      sessionId,\n      timestamp: state.startedAt,\n      configHash: this.opts.configHash\n    })\n    return state\n  }\n\n  registerSession(sessionId: string, source: 'log_tail' | 'ipc_push' = 'ipc_push'): void {\n    this.getOrCreate(sessionId, source)\n  }\n\n  /** 幂等摄入一个 reasoning 块: 块内 sequence 只增不减 */\n  ingest(block: ReasoningBlock): void {\n    const state = this.getOrCreate(block.sessionId, block.source === 'log' ? 'log_tail' : 'ipc_push')\n    const seq = block.sequence > 0 ? block.sequence : state.lastSequence + 1\n    if (seq <= state.lastSequence) return // 重复/乱序块丢弃\n    state.lastSequence = seq\n    state.blockCount += 1\n    state.lastActivityAt = Date.now()\n    state.lastReasoningAt = Date.now()\n    if (block.workspace !== undefined) state.workspace = block.workspace\n    if (block.title !== undefined) state.title = block.title\n\n    this.opts.emit({\n      type: 'block_received',\n      sessionId: block.sessionId,\n      timestamp: block.timestamp,\n      sequence: seq,\n      textLength: block.text.length\n    })\n\n    const vec = this.opts.extractor.extract(block)\n    const snap = state.window.push(vec, block.timestamp)\n    this.opts.emit({\n      type: 'window_updated',\n      sessionId: block.sessionId,\n      timestamp: block.timestamp,\n      sequence: seq,\n      windowId: snap.windowId,\n      windowSize: snap.size,\n      features: snap.features\n    })\n\n    const cfg = this.opts.config\n    const scored = this.opts.scoring.compute({\n      snap,\n      rawHistory: state.rawHistory,\n      percentileWindow: cfg.scoring.percentile_window\n    })\n    state.rawHistory.push(scored.raw)\n    if (state.rawHistory.length > cfg.scoring.percentile_window) state.rawHistory.shift()\n    state.normalizedHistory.push(scored.normalized)\n    if (state.normalizedHistory.length > MAX_NORMALIZED_HISTORY) state.normalizedHistory.shift()\n\n    const baseline = state.baseline.push(scored.normalized)\n    const trend = computeTrend(state.normalizedHistory, cfg.threshold.trend_window, cfg.threshold.trend_slope_sigma)\n    const ratio = personaRatio(snap, this.opts.lexicon)\n    const band = this.bandOf(ratio, state.baseline)\n    const confidence =\n      Math.min(1, state.baseline.size / cfg.threshold.baseline_min_samples) *\n      (cfg.window.type === 'sliding' ? Math.min(1, snap.size / cfg.window.size) : 1)\n\n    this.opts.emit({\n      type: 'score_computed',\n      sessionId: block.sessionId,\n      timestamp: block.timestamp,\n      sequence: seq,\n      windowSize: snap.size,\n      score: scored.raw,\n      normalizedScore: scored.normalized,\n      band,\n      trend,\n      features: { ...snap.features, ratio: ratio ?? -1, confidence },\n      baselineMean: baseline.mean,\n      baselineStd: baseline.std,\n      phase: state.phase,\n      percentile: scored.percentile\n    })\n\n    const anomaly = checkAnomalies({\n      normalized: scored.normalized,\n      percentile: scored.percentile,\n      baseline,\n      personaRatio: ratio,\n      config: cfg.threshold,\n      bands: cfg.bands\n    })\n    this.opts.emit({\n      type: 'threshold_check',\n      sessionId: block.sessionId,\n      timestamp: block.timestamp,\n      sequence: seq,\n      triggered: anomaly.triggered,\n      matched: anomaly.matched\n    })\n\n    const recovered = isRecovered({\n      normalized: scored.normalized,\n      baseline,\n      trend,\n      ratio,\n      bands: cfg.bands,\n      config: cfg.threshold\n    })\n\n    const decision = decideIntervention({\n      phase: state.phase,\n      trend,\n      anomalyTriggered: anomaly.triggered,\n      anomalySeverity: anomaly.severity,\n      bandHit: anomaly.bandHit,\n      recovered,\n      l2Attempts: state.l2Attempts,\n      config: cfg.intervention\n    })\n    if (!this.interventionsEnabled && decision.level !== 'none') {\n      // 干预总开关关闭: 只监控不干预(评分/波段/阈值事件照常, 决策被拦截)\n      decision.level = 'none'\n      decision.nextPhase = 'healthy'\n      decision.resetL2Attempts = true\n      decision.reason = 'interventions disabled'\n    }\n    state.lastNormalized = scored.normalized\n    if (decision.resetL2Attempts) state.l2Attempts = 0\n\n    if (decision.level !== 'none' && state.phase !== 'restart') {\n      if (!state.cooldowns.isReady(decision.level, block.timestamp)) {\n        this.opts.emit({\n          type: 'intervention_executed',\n          sessionId: block.sessionId,\n          timestamp: block.timestamp,\n          sequence: seq,\n          level: decision.level,\n          status: 'cooldown'\n        })\n      } else {\n        const signal = this.buildSignal(state, decision.level, decision.reason, block.timestamp)\n        state.cooldowns.markSent(decision.level, block.timestamp)\n        state.phase = decision.nextPhase\n        if (decision.level === 'L2') {\n          state.l2Attempts += 1\n          this.resetWindow(state)\n        }\n        if (decision.level === 'L3') state.phase = 'restart'\n        state.interventions.push({\n          level: decision.level,\n          reason: decision.reason,\n          timestamp: block.timestamp,\n          sequence: seq,\n          status: 'sent',\n          payload: signal.payload\n        })\n        this.opts.emit({\n          type: 'intervention_triggered',\n          sessionId: block.sessionId,\n          timestamp: block.timestamp,\n          sequence: seq,\n          level: decision.level,\n          reason: decision.reason,\n          payload: signal.payload\n        })\n        void this.opts.sender.send(signal)\n      }\n    } else if (decision.nextPhase !== state.phase) {\n      state.phase = decision.nextPhase\n    }\n\n    const point: HistoryPoint = {\n      sequence: seq,\n      timestamp: block.timestamp,\n      score: scored.raw,\n      normalizedScore: scored.normalized,\n      band,\n      trend,\n      phase: state.phase,\n      ratio,\n      confidence,\n      percentile: scored.percentile,\n      windowAggregate: { ...snap.aggregate }\n    }\n    state.history.push(point)\n    if (state.history.length > MAX_HISTORY_POINTS) state.history.shift()\n  }\n\n  /** text 信道指纹比: 与 personaRatio 同口径(负向词数/(正向+负向)), 但只在最近 text 样本上算 */\n  private textThinkRatio(state: SessionState): number {\n    const sample = state.textSample\n    if (!sample) return 0\n    const vec = this.opts.extractor.extract({ sessionId: state.sessionId, timestamp: Date.now(), sequence: 0, text: sample, source: 'ipc' })\n    let pos = 0\n    let neg = 0\n    for (const t of this.opts.lexicon.positiveTerms) pos += vec.counts[t] ?? 0\n    for (const t of this.opts.lexicon.negativeTerms) neg += vec.counts[t] ?? 0\n    const total = pos + neg\n    return total > 0 ? neg / total : 0\n  }\n\n  /** CoT 守卫评估: text 泄漏 + reasoning 停摆(仅告警, 不自动干预) */\n  private evaluateGuards(state: SessionState, now: number): void {\n    const cfg = this.opts.config.guards?.cot\n    if (!cfg || !cfg.enabled) return\n    // 1) text_leak: 窗口内字符数达标 + 思考样式指纹密度达标 → 思考泄漏进可见正文\n    if (now - state.guardLastAt.leak >= cfg.cooldown_ms) {\n      const windowChars = state.textTimes.reduce((s, t) => s + t.chars, 0)\n      if (windowChars >= cfg.text_surge_chars) {\n        const ratio = this.textThinkRatio(state)\n        if (ratio >= cfg.text_leak_ratio) {\n          state.cotAlerts.leak += 1\n          state.guardLastAt.leak = now\n          state.lastAlertAt = now\n          this.opts.emit({\n            type: 'guard_triggered',\n            sessionId: state.sessionId,\n            timestamp: now,\n            guard: 'text_leak',\n            detail: 'text 信道 ' + windowChars + ' chars/『' + cfg.text_surge_window_ms + 'ms』, 思考样式指纹比 ' + ratio.toFixed(2)\n          })\n        }\n      }\n    }\n    // 2) stream_stall: 见过 reasoning, 且已停摆超过阈值, 但 text 信道仍在出内容\n    if (state.blockCount > 0 && now - state.lastReasoningAt > cfg.reasoning_stall_ms) {\n      if (now - state.lastTextAt <= cfg.text_active_window_ms) {\n        if (now - state.guardLastAt.stall >= cfg.cooldown_ms) {\n          state.cotAlerts.stall += 1\n          state.guardLastAt.stall = now\n          state.lastAlertAt = now\n          this.opts.emit({\n            type: 'guard_triggered',\n            sessionId: state.sessionId,\n            timestamp: now,\n            guard: 'streaming_stall',\n            detail: 'reasoning 停摆 ' + Math.round((now - state.lastReasoningAt) / 1000) + 's, text 仍在输出'\n          })\n        }\n      }\n    }\n  }\n\n  /** 摄入一个 text 信道增量(可见正文): 更新计数并做 CoT 泄漏/停摆评估 */\n  ingestText(block: TextChunkBlock): void {\n    const cfg = this.opts.config.guards?.cot\n    if (!cfg || !cfg.enabled) return\n    const state = this.getOrCreate(block.sessionId, 'ipc_push')\n    const seq = block.sequence > 0 ? block.sequence : state.textSeq + 1\n    if (seq <= state.textSeq) return // 重复/乱序丢弃\n    state.textSeq = seq\n    state.textChunks += 1\n    state.textChars += block.text.length\n    state.lastTextAt = Date.now()\n    state.lastActivityAt = state.lastTextAt\n    if (block.workspace !== undefined) state.workspace = block.workspace\n    if (block.title !== undefined) state.title = block.title\n    const maxSample = Math.max(cfg.text_surge_chars, 2000)\n    state.textSample = (state.textSample + block.text).slice(-maxSample)\n    const now = Date.now()\n    state.textTimes.push({ at: now, chars: block.text.length })\n    const w = cfg.text_surge_window_ms\n    while (state.textTimes.length > 0 && now - state.textTimes[0].at > w) state.textTimes.shift()\n\n    this.opts.emit({\n      type: 'text_chunk_received',\n      sessionId: block.sessionId,\n      timestamp: now,\n      sequence: seq,\n      textLength: block.text.length\n    })\n    this.evaluateGuards(state, now)\n  }\n\n  private buildSignal(\n    state: SessionState,\n    level: Exclude<InterventionLevel, 'none'>,\n    reason: string,\n    timestamp: number\n  ): InterventionSignal {\n    const cfg = this.opts.config\n    if (level === 'L1') {\n      const l1Count = state.interventions.filter((i) => i.level === 'L1').length\n      const id = l1Count % Math.max(1, cfg.intervention.hint_templates.length)\n      const hintText = cfg.intervention.hint_templates[id] ?? ''\n      return {\n        sessionId: state.sessionId,\n        level,\n        payload: { hintTemplateId: id, hintText },\n        reason,\n        timestamp\n      }\n    }\n    if (level === 'L2') {\n      return {\n        sessionId: state.sessionId,\n        level,\n        payload: {\n          reset: {\n            systemPrompt: cfg.intervention.bootstrap_system_prompt,\n            tools: cfg.intervention.bootstrap_tools\n          }\n        },\n        reason,\n        timestamp\n      }\n    }\n    return {\n      sessionId: state.sessionId,\n      level,\n      payload: { message: reason },\n      reason,\n      timestamp\n    }\n  }\n\n  /** L2 强制重置后清空窗口与基线, 防止历史数据污染后续判断 */\n  private resetWindow(state: SessionState): void {\n    state.window.reset()\n    state.baseline.reset()\n    state.rawHistory = []\n    state.normalizedHistory = []\n    state.lastNormalized = null\n    // L2 重置后重新计时: 停摆守卫时钟重启, 期待新一轮 reasoning\n    state.lastReasoningAt = Date.now()\n    state.textTimes = []\n    state.textSample = ''\n  }\n\n  /** 手动触发一次 L2 重置(测试/运维入口) */\n  forceReset(sessionId: string): InterventionSignal | null {\n    const state = this.sessions.get(sessionId)\n    if (!state) return null\n    const signal = this.buildSignal(state, 'L2', 'manual reset', Date.now())\n    state.phase = 'critical'\n    state.l2Attempts += 1\n    this.resetWindow(state)\n    state.interventions.push({\n      level: 'L2',\n      reason: 'manual reset',\n      timestamp: Date.now(),\n      sequence: state.lastSequence,\n      status: 'sent',\n      payload: signal.payload\n    })\n    this.opts.emit({\n      type: 'intervention_triggered',\n      sessionId,\n      timestamp: signal.timestamp,\n      sequence: state.lastSequence,\n      level: 'L2',\n      reason: 'manual reset',\n      payload: signal.payload\n    })\n    void this.opts.sender.send(signal)\n    return signal\n  }\n\n  ack(sessionId: string, level: Exclude<InterventionLevel, 'none'>, status: string): boolean {\n    const state = this.sessions.get(sessionId)\n    if (!state) return false\n    for (let i = state.interventions.length - 1; i >= 0; i--) {\n      const rec = state.interventions[i]\n      if (rec.level === level && rec.status === 'sent') {\n        rec.status = 'acked'\n        rec.ackedAt = Date.now()\n        this.opts.emit({\n          type: 'ack_received',\n          sessionId,\n          timestamp: Date.now(),\n          level,\n          status\n        })\n        return true\n      }\n    }\n    return false\n  }\n\n  endSession(sessionId: string, reason: string): void {\n    const state = this.sessions.get(sessionId)\n    if (!state) return\n    state.ended = true\n    this.opts.emit({ type: 'session_end', sessionId, timestamp: Date.now(), reason })\n  }\n\n  listSummaries(): SessionSummary[] {\n    const out: SessionSummary[] = []\n    for (const s of this.sessions.values()) {\n      const last = s.history[s.history.length - 1]\n      out.push({\n        sessionId: s.sessionId,\n        workspace: s.workspace,\n        title: s.title,\n        phase: s.phase,\n        blockCount: s.blockCount,\n        lastSequence: s.lastSequence,\n        normalizedScore: last ? last.normalizedScore : null,\n        band: last ? last.band : 'unknown',\n        interventions: s.interventions.length,\n        lastActivityAt: s.lastActivityAt,\n        source: s.source,\n        cot: {\n          textChars: s.textChars,\n          textChunks: s.textChunks,\n          alerts: s.cotAlerts.stall + s.cotAlerts.leak,\n          stallAlerts: s.cotAlerts.stall,\n          leakAlerts: s.cotAlerts.leak,\n          lastAlertAt: s.lastAlertAt\n        }\n      })\n    }\n    return out\n  }\n\n  getSnapshot(sessionId: string): SessionSnapshot | null {\n    const s = this.sessions.get(sessionId)\n    if (!s) return null\n    const baseline = s.baseline.stats()\n    const last = s.history[s.history.length - 1]\n    return {\n      sessionId,\n      phase: s.phase,\n      startedAt: s.startedAt,\n      lastSequence: s.lastSequence,\n      blockCount: s.blockCount,\n      window: s.window.current,\n      latest: last\n        ? {\n            score: last.score,\n            normalizedScore: last.normalizedScore,\n            band: last.band,\n            confidence: last.confidence,\n            components: {},\n            trend: last.trend,\n            percentile: last.percentile\n          }\n        : null,\n      baseline: { mean: baseline.mean, std: baseline.std, samples: baseline.samples },\n      interventions: s.interventions.map((i) => ({\n        level: i.level,\n        reason: i.reason,\n        timestamp: i.timestamp,\n        sequence: i.sequence,\n        status: i.status,\n        ackedAt: i.ackedAt\n      })),\n      l2Attempts: s.l2Attempts,\n      history: s.history.map((h) => ({\n        sequence: h.sequence,\n        timestamp: h.timestamp,\n        score: h.score,\n        normalizedScore: h.normalizedScore,\n        band: h.band,\n        trend: h.trend,\n        phase: h.phase,\n        ratio: h.ratio,\n        windowAggregate: h.windowAggregate\n      })),\n      cooldowns: s.cooldowns.snapshot(Date.now()),\n      cot: {\n        textChars: s.textChars,\n        textChunks: s.textChunks,\n        alerts: s.cotAlerts.stall + s.cotAlerts.leak,\n        stallAlerts: s.cotAlerts.stall,\n        leakAlerts: s.cotAlerts.leak,\n        lastAlertAt: s.lastAlertAt\n      }\n    }\n  }\n}\n"
    },
    {
      "path": "src/monitor/server.ts",
      "content": "/**\n * 监控进程 HTTP 服务: REST API + SSE 实时流 + 仪表盘静态托管\n */\n\nimport { createServer, type IncomingMessage, type ServerResponse, type Server } from 'node:http'\nimport { readFile } from 'node:fs/promises'\nimport { closeSync, fstatSync, openSync, readSync } from 'node:fs'\nimport { extname, join } from 'node:path'\nimport type { InterventionSignal, MonitorConfig, MonitorEvent } from '../shared/types.js'\nimport type { SessionManager } from './session-manager.js'\nimport { IPC } from '../shared/ipc-protocol.js'\n\nexport interface MonitorServer {\n  server: Server\n  port: number\n  url: string\n  broadcast: (event: MonitorEvent | InterventionSignal) => void\n}\n\nexport interface StartServerOptions {\n  config: MonitorConfig\n  configHash: string\n  manager: SessionManager\n  root: string\n  /** 实验日志 JSONL 的绝对路径(供 /api/events 尾读) */\n  logPath: string\n  /** 日志型事件源注册回调(由入口装配) */\n  registerSource?: (sessionId: string, logPath?: string) => Promise<void>\n  onLog?: (message: string) => void\n}\n\ninterface SseClient {\n  res: ServerResponse\n  sessionId: string | null\n}\n\nconst MIME: Record<string, string> = {\n  '.html': 'text/html; charset=utf-8',\n  '.css': 'text/css; charset=utf-8',\n  '.js': 'text/javascript; charset=utf-8',\n  '.svg': 'image/svg+xml',\n  '.json': 'application/json; charset=utf-8',\n  '.png': 'image/png'\n}\n\nconst STATIC_FILES: Record<string, string> = {\n  '/': 'index.html',\n  '/index.html': 'index.html',\n  '/styles.css': 'styles.css',\n  '/app.js': 'app.js',\n  '/favicon.svg': 'favicon.svg'\n}\n\nfunction setCors(res: ServerResponse): void {\n  res.setHeader('Access-Control-Allow-Origin', '*')\n  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')\n  res.setHeader('Access-Control-Allow-Headers', 'Content-Type')\n}\n\nfunction json(res: ServerResponse, code: number, payload: unknown): void {\n  const body = JSON.stringify(payload)\n  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' })\n  res.end(body)\n}\n\n/** 尾读 JSONL 文件(最多读尾部 maxBytes 字节), 返回最近若干事件 */\nfunction readTailJsonl(filePath: string, maxBytes = 512 * 1024): unknown[] {\n  try {\n    const fd = openSync(filePath, 'r')\n    try {\n      const size = fstatSync(fd).size\n      const start = Math.max(0, size - maxBytes)\n      const buf = Buffer.alloc(size - start)\n      readSync(fd, buf, 0, buf.length, start)\n      const lines = buf.toString('utf8').split('\\n').filter((l) => l.trim().length > 0)\n      const tail = lines.slice(-400)\n      const out: unknown[] = []\n      for (const line of tail) {\n        try {\n          out.push(JSON.parse(line) as unknown)\n        } catch {\n          // 跳过损坏行\n        }\n      }\n      return out\n    } finally {\n      closeSync(fd)\n    }\n  } catch {\n    return []\n  }\n}\n\nfunction readJsonBody(req: IncomingMessage, limitBytes: number): Promise<Record<string, unknown>> {\n  return new Promise((resolve, reject) => {\n    const chunks: Buffer[] = []\n    let size = 0\n    req.on('data', (chunk: Buffer) => {\n      size += chunk.length\n      if (size > limitBytes) {\n        reject(new Error('body too large'))\n        req.destroy()\n        return\n      }\n      chunks.push(chunk)\n    })\n    req.on('end', () => {\n      try {\n        const text = Buffer.concat(chunks).toString('utf8')\n        const parsed = text.length === 0 ? {} : (JSON.parse(text) as unknown)\n        if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {\n          reject(new Error('body must be a JSON object'))\n          return\n        }\n        resolve(parsed as Record<string, unknown>)\n      } catch (err) {\n        reject(err instanceof Error ? err : new Error('invalid JSON'))\n      }\n    })\n    req.on('error', reject)\n  })\n}\n\nexport async function startServer(opts: StartServerOptions): Promise<MonitorServer> {\n  const clients = new Set<SseClient>()\n  const webRoot = join(opts.root, opts.config.dashboard.web_root.replace(/^\\.\\//, ''))\n  let broadcast: MonitorServer['broadcast'] = () => {}\n\n  const server = createServer((req, res) => {\n    setCors(res)\n    if (req.method === 'OPTIONS') {\n      res.writeHead(204)\n      res.end()\n      return\n    }\n    const url = new URL(req.url ?? '/', 'http://localhost')\n    const path = url.pathname\n    void (async () => {\n      try {\n        if (path === '/api/health' && req.method === 'GET') {\n          return json(res, 200, {\n            ok: true,\n            uptimeMs: Math.round(process.uptime() * 1000),\n            version: opts.config.version,\n            sessions: opts.manager.listSummaries().length\n          })\n        }\n        if (path === '/api/shutdown' && req.method === 'POST') {\n          const address = req.socket.remoteAddress ?? ''\n          if (address !== '127.0.0.1' && address !== '::1' && address !== '::ffff:127.0.0.1') {\n            return json(res, 403, { ok: false, error: 'loopback-only' })\n          }\n          json(res, 200, { ok: true })\n          setTimeout(() => process.exit(0), 150)\n          return\n        }\n        if (path === '/api/config' && req.method === 'GET') {\n          return json(res, 200, opts.config)\n        }\n        if (path === '/api/intervention' && req.method === 'GET') {\n          return json(res, 200, { ok: true, enabled: opts.manager.isInterventionsEnabled() })\n        }\n        if (path === '/api/intervention' && req.method === 'POST') {\n          const body = await readJsonBody(req, 1024 * 16)\n          if (!body || typeof body.enabled !== 'boolean') {\n            return json(res, 400, { ok: false, error: '需要 { enabled: boolean }' })\n          }\n          opts.manager.setInterventionsEnabled(body.enabled)\n          return json(res, 200, { ok: true, enabled: opts.manager.isInterventionsEnabled() })\n        }\n        if (path === '/api/sessions' && req.method === 'GET') {\n          return json(res, 200, opts.manager.listSummaries())\n        }\n        if (path === '/api/events' && req.method === 'GET') {\n          const sessionFilter = url.searchParams.get('sessionId')\n          const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit') ?? 50) || 50))\n          const all = readTailJsonl(opts.logPath) as Array<{ sessionId?: string }>\n          const filtered = sessionFilter ? all.filter((e) => e.sessionId === sessionFilter) : all\n          return json(res, 200, filtered.slice(-limit))\n        }\n        if (path === '/api/overview' && req.method === 'GET') {\n          const summaries = opts.manager.listSummaries()\n          const requested = url.searchParams.get('sessionId')\n          const sessionId = requested ?? summaries[0]?.sessionId ?? null\n          const snapshot = sessionId ? opts.manager.getSnapshot(sessionId) : null\n          const limit = Math.min(60, Math.max(1, Number(url.searchParams.get('limit') ?? 30) || 30))\n          const all = readTailJsonl(opts.logPath) as Array<{ sessionId?: string }>\n          const events = (sessionId ? all.filter((e) => e.sessionId === sessionId) : all).slice(-limit)\n          return json(res, 200, {\n            ok: true,\n            monitorOnline: true,\n            version: opts.config.version,\n            configHash: opts.configHash,\n            bands: opts.config.bands,\n            thresholds: {\n              specMax: opts.config.bands.spec_max,\n              reactMin: opts.config.bands.react_min,\n              safetyFloor: opts.config.threshold.safety_floor\n            },\n            triggers: {\n              mixed: opts.config.threshold.trigger.some((r) => r.type === 'mixed_band'),\n              react: opts.config.threshold.trigger.some((r) => r.type === 'react_band'),\n              sigma: opts.config.threshold.trigger.some((r) => r.type === 'sigma'),\n              percentile: opts.config.threshold.trigger.some((r) => r.type === 'percentile'),\n              floor: opts.config.threshold.trigger.some((r) => r.type === 'safety_floor')\n            },\n            cooldowns: opts.config.intervention.cooldowns,\n            maxL2Attempts: opts.config.intervention.max_L2_attempts,\n            bootstrapTools: opts.config.intervention.bootstrap_tools,\n            guards: opts.config.guards,\n            interventionsEnabled: opts.manager.isInterventionsEnabled(),\n            sessions: summaries,\n            selected: sessionId,\n            snapshot,\n            events\n          })\n        }\n        if (path === '/api/stream' && req.method === 'GET') {\n          res.writeHead(200, {\n            'Content-Type': 'text/event-stream',\n            'Cache-Control': 'no-cache',\n            Connection: 'keep-alive'\n          })\n          const client: SseClient = { res, sessionId: url.searchParams.get('sessionId') }\n          clients.add(client)\n          res.write(`data: ${JSON.stringify({ type: 'stream_ready', timestamp: Date.now() })}\\n\\n`)\n          const ping = setInterval(() => {\n            try {\n              res.write(': ping\\n\\n')\n            } catch {\n              clearInterval(ping)\n            }\n          }, 15000)\n          req.on('close', () => {\n            clearInterval(ping)\n            clients.delete(client)\n          })\n          return\n        }\n        if (path === '/api/push' && req.method === 'POST') {\n          const body = await readJsonBody(req, 1024 * 1024)\n          const sessionId = body.sessionId\n          const text = body.text\n          if (typeof sessionId !== 'string' || sessionId.length === 0 || typeof text !== 'string') {\n            return json(res, 400, { ok: false, error: 'push 需要 { sessionId: string, text: string }' })\n          }\n          const block = {\n            sessionId,\n            text,\n            sequence: typeof body.sequence === 'number' ? body.sequence : 0,\n            timestamp: typeof body.timestamp === 'number' ? body.timestamp : Date.now(),\n            source: 'ipc' as const,\n            workspace: typeof body.workspace === 'string' ? body.workspace : undefined,\n            title: typeof body.title === 'string' ? body.title : undefined\n          }\n          opts.manager.ingest(block)\n          return json(res, 200, { ok: true, sessionId })\n        }\n        if (path === '/api/push-text' && req.method === 'POST') {\n          const body = await readJsonBody(req, 1024 * 1024)\n          const sessionId = body.sessionId\n          const text = body.text\n          if (typeof sessionId !== 'string' || sessionId.length === 0 || typeof text !== 'string') {\n            return json(res, 400, { ok: false, error: 'push-text 需要 { sessionId: string, text: string }' })\n          }\n          const chunk = {\n            sessionId,\n            text,\n            sequence: typeof body.sequence === 'number' ? body.sequence : 0,\n            timestamp: typeof body.timestamp === 'number' ? body.timestamp : Date.now(),\n            source: 'ipc' as const,\n            workspace: typeof body.workspace === 'string' ? body.workspace : undefined,\n            title: typeof body.title === 'string' ? body.title : undefined\n          }\n          opts.manager.ingestText(chunk)\n          return json(res, 200, { ok: true, sessionId })\n        }\n        const sessionMatch = path.match(/^\\/api\\/sessions\\/([^/]+)$/)\n        if (sessionMatch && req.method === 'GET') {\n          const snap = opts.manager.getSnapshot(decodeURIComponent(sessionMatch[1]))\n          if (!snap) return json(res, 404, { ok: false, error: 'session not found' })\n          return json(res, 200, snap)\n        }\n        const registerMatch = path.match(/^\\/api\\/sessions\\/([^/]+)\\/register$/)\n        if (registerMatch && req.method === 'POST') {\n          const sessionId = decodeURIComponent(registerMatch[1])\n          const body = await readJsonBody(req, 1024 * 1024)\n          const logPath = typeof body.logPath === 'string' ? body.logPath : undefined\n          opts.manager.registerSession(sessionId, 'log_tail')\n          await opts.registerSource?.(sessionId, logPath)\n          return json(res, 200, { ok: true, sessionId })\n        }\n        const ackMatch = path.match(/^\\/api\\/sessions\\/([^/]+)\\/ack$/)\n        if (ackMatch && req.method === 'POST') {\n          const sessionId = decodeURIComponent(ackMatch[1])\n          const body = await readJsonBody(req, 1024 * 1024)\n          const level = body.level\n          if (level !== 'L1' && level !== 'L2' && level !== 'L3') {\n            return json(res, 400, { ok: false, error: 'level 必须是 L1/L2/L3' })\n          }\n          const ok = opts.manager.ack(sessionId, level, typeof body.status === 'string' ? body.status : 'executed')\n          return json(res, ok ? 200 : 404, { ok })\n        }\n        const resetMatch = path.match(/^\\/api\\/sessions\\/([^/]+)\\/reset$/)\n        if (resetMatch && req.method === 'POST') {\n          const signal = opts.manager.forceReset(decodeURIComponent(resetMatch[1]))\n          if (!signal) return json(res, 404, { ok: false, error: 'session not found' })\n          return json(res, 200, { ok: true, signal })\n        }\n        const staticFile = STATIC_FILES[path]\n        if (staticFile && req.method === 'GET') {\n          try {\n            const data = await readFile(join(webRoot, staticFile))\n            res.writeHead(200, { 'Content-Type': MIME[extname(staticFile)] ?? 'application/octet-stream' })\n            res.end(data)\n          } catch {\n            res.writeHead(404)\n            res.end('not found')\n          }\n          return\n        }\n        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' })\n        res.end(JSON.stringify({ ok: false, error: 'not found' }))\n      } catch (err) {\n        json(res, 500, { ok: false, error: err instanceof Error ? err.message : String(err) })\n      }\n    })()\n  })\n\n  broadcast = (event) => {\n    const line = `data: ${JSON.stringify(event)}\\n\\n`\n    for (const client of clients) {\n      if (client.sessionId !== null && client.sessionId !== (event as { sessionId?: string }).sessionId) continue\n      try {\n        client.res.write(line)\n      } catch {\n        clients.delete(client)\n      }\n    }\n  }\n\n  const port = opts.config.dashboard.port\n  await new Promise<void>((resolve, reject) => {\n    server.once('error', reject)\n    server.listen(port, opts.config.dashboard.host, () => resolve())\n  })\n  const url = `http://${opts.config.dashboard.host}:${port}`\n  opts.onLog?.(`仪表盘: ${url}`)\n  return { server, port, url, broadcast }\n}\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * @a9i5k4/dsh-anchored-monitor — host half(零运行时依赖, 仅 node 内置模块)。\n *\n * 职责:\n *  1. 自动拉起独立监控进程(autoStart, 默认开): DSH 启动即检测/拉起\n *     node <pkg>/dist/monitor/index.js --profile <profile> --overrides <json>,\n *     15s watchdog 保活; 用户零操作。\n *  2. 真实会话监控: 监听 'session/event', 把每个 assistant/message 的\n *     reasoning 块 POST /api/push 推给监控进程(所有会话自动覆盖)。\n *  3. 真实干预: 轮询监控进程事件流, 检测到 L1/L2/L3 后执行——\n *     L1: agent/pre-step 注入建议式提示消息; L2: system-prompt/assemble\n *     替换 persona 段为 Minimal 46 字符句 + 工具目录收缩为 bootstrap 双工具;\n *     L3: 注入建议重启的消息; 执行后回 ack。\n *  4. 设置面: /api/anchored-monitor/settings GET/POST 读写宿主配置与\n *     监控 overrides(保存后自动重启监控进程生效)。\n *  5. /api/anchored-monitor/* 同源代理(loopback-only) + 系统提示词宣发段。\n */\n\nimport { spawn } from 'node:child_process'\nimport { mkdir, readFile, writeFile } from 'node:fs/promises'\nimport { homedir } from 'node:os'\nimport path from 'node:path'\nimport { fileURLToPath } from 'node:url'\n\n/** Stable cordis plugin name(与 cordis.patch.yml insert id 一致)。 */\nexport const name = 'anchored-monitor'\n\n/** 挂载所需服务(agents 用于干预后自动续跑 followup)。 */\nexport const inject = ['webServer', 'systemPrompt', 'agents']\n\nconst SECTION_ORDER = 210\nconst API_PREFIX = '/api/anchored-monitor'\nconst DEFAULT_MONITOR_URL = 'http://127.0.0.1:9301'\nconst UPDATE_RAW_URL = 'https://raw.githubusercontent.com/Aik358/dsh-anchored-monitor/main/package.json'\nconst UPDATE_TTL_MS = 12 * 3600 * 1000\nlet updateCache = null\nconst PACKAGE_ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)))\nconst MONITOR_ENTRY = path.join(PACKAGE_ROOT, 'dist', 'monitor', 'index.js')\n\nfunction homeFile(...parts) {\n  return path.join(homedir(), '.dsh', ...parts)\n}\nfunction configPath() {\n  return homeFile('anchored-monitor.json')\n}\nfunction overridesPath() {\n  return homeFile('anchored-monitor.overrides.json')\n}\n\n/** Model-facing announcement。 */\nexport const GUIDANCE = '本机已安装 dsh-anchored-monitor 插件（实时思维链锚定监控与干预）：DSH 启动时自动拉起独立监控进程，按 we/let\\'s/let me 指纹持续评估每个会话思维链所处波段（spec 稳定带 <0.2 / mixed 过渡带 0.2-0.5 / react 行动者带 >=0.5）。GUI 左侧栏「锚定监控」入口可打开液体毛玻璃浮层面板查看实时波段/强度分/趋势与干预级联，收起时以变阻器式悬浮条显示思考强度与最近日志（可选「滑动变祖器」梗皮肤：小方块按强度从夯到拉切换梁文锋表情）；设置页可调整全部技术参数（窗口/词典/评分权重/波段边界/阈值/冷却/提示模板/日志）与皮肤。干预自动执行：L1 温和引导（建议式措辞注入下一轮，禁止命令式）/ L2 强制重置（persona 切回 Minimal 46 字符句 + bash/str_replace_editor 双工具，监控窗口与基线清零）/ L3 建议会话重启。用户提到「锚定监控 / 思维链监控 / 波段 / 思考强度」时即指本插件，请据此协作。'\n\nfunction semverGt(a, b) {\n  const pa = String(a).split('.').map(function (x) { return Number(x) || 0 })\n  const pb = String(b).split('.').map(function (x) { return Number(x) || 0 })\n  for (let i = 0; i < 3; i++) {\n    if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) > (pb[i] || 0)\n  }\n  return false\n}\n\nfunction isLoopbackRequest(req) {\n  const address = req && req.socket && req.socket.remoteAddress ? req.socket.remoteAddress : ''\n  if (address !== '127.0.0.1' && address !== '::1' && address !== '::ffff:127.0.0.1') return false\n  const host = req && req.headers && req.headers.host ? req.headers.host : ''\n  const hostname = host.split(':')[0]\n  return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '[::1]'\n}\n\nfunction writeJson(res, code, payload) {\n  const body = JSON.stringify(payload)\n  res.writeHead(code, { 'content-type': 'application/json; charset=utf-8' })\n  res.end(body)\n}\n\nasync function readJsonBody(req) {\n  const chunks = []\n  let total = 0\n  for await (const chunk of req) {\n    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)\n    chunks.push(buffer)\n    total += buffer.length\n    if (total > 256 * 1024) return null\n  }\n  const text = Buffer.concat(chunks).toString('utf8')\n  if (text === '') return null\n  try {\n    return JSON.parse(text)\n  } catch {\n    return null\n  }\n}\n\n/** 把请求原样转发到监控进程(带 2.5s 超时); 离线时返回 502 + 提示。 */\nasync function proxyGet(monitorUrl, req, res, monitorPath) {\n  try {\n    const qIndex = (req.url || '').indexOf('?')\n    const query = qIndex >= 0 ? req.url.slice(qIndex) : ''\n    const upstream = await fetch(monitorUrl + monitorPath + query, { signal: AbortSignal.timeout(2500) })\n    const body = await upstream.text()\n    res.writeHead(upstream.status, { 'content-type': 'application/json; charset=utf-8' })\n    res.end(body)\n  } catch (err) {\n    writeJson(res, 502, {\n      ok: false,\n      monitorOnline: false,\n      error: 'monitor-offline',\n      hint: '监控进程离线(正在自动拉起, 请稍候)',\n      detail: String(err && err.message ? err.message : err)\n    })\n  }\n}\n\nexport function apply(ctx) {\n  let config = { monitorUrl: DEFAULT_MONITOR_URL, enabled: true, autoStart: true, profile: 'default', monitorOverrides: {} }\n  const reload = async () => {\n    let parsed = {}\n    try {\n      parsed = JSON.parse(await readFile(configPath(), 'utf8'))\n    } catch {\n      parsed = {}\n    }\n    config = {\n      monitorUrl: typeof parsed.monitorUrl === 'string' && parsed.monitorUrl !== '' ? parsed.monitorUrl : (process.env.ANCHORED_MONITOR_URL || DEFAULT_MONITOR_URL),\n      enabled: parsed.enabled !== false,\n      autoStart: parsed.autoStart !== false,\n      profile: typeof parsed.profile === 'string' && parsed.profile !== '' ? parsed.profile : 'default',\n      monitorOverrides: parsed.monitorOverrides && typeof parsed.monitorOverrides === 'object' ? parsed.monitorOverrides : {}\n    }\n  }\n\n  const warned = new Set()\n  const warnOnce = (message) => {\n    if (warned.has(message)) return\n    warned.add(message)\n    try {\n      ctx.logger.warn(message)\n    } catch {\n      // logger 不可用时仅避免刷屏\n    }\n  }\n  // 干预执行/轮询的可观测日志: 优先 ctx.logger, 退化到 console(宿主进程 stdout)\n  const logInfo = (message) => {\n    try {\n      if (ctx.logger && typeof ctx.logger.info === 'function') ctx.logger.info(message)\n      else console.log(message)\n    } catch {\n      try { console.log(message) } catch { /* 忽略 */ }\n    }\n  }\n\n  // ── 1) 监控进程生命周期: 自动拉起 + watchdog ──\n  let monitorProc = null\n  let monitorBusy = false\n  const isMonitorOnline = async (url) => {\n    try {\n      const r = await fetch(url + '/api/health', { signal: AbortSignal.timeout(1500) })\n      return r.ok\n    } catch {\n      return false\n    }\n  }\n  const ensureMonitorRunning = async () => {\n    if (monitorBusy) return\n    monitorBusy = true\n    try {\n      if (!config.enabled || !config.autoStart) return\n      if (await isMonitorOnline(config.monitorUrl)) return\n      try {\n        await mkdir(homeFile(), { recursive: true })\n        await writeFile(overridesPath(), JSON.stringify(config.monitorOverrides ?? {}, null, 2), 'utf8')\n      } catch (err) {\n        warnOnce('anchored-monitor: overrides 文件写入失败: ' + String(err && err.message ? err.message : err))\n      }\n      monitorProc = spawn(process.execPath, [MONITOR_ENTRY, '--profile', config.profile, '--overrides', overridesPath()], {\n        detached: true,\n        stdio: 'ignore',\n        windowsHide: true,\n        cwd: PACKAGE_ROOT\n      })\n      monitorProc.unref()\n      for (let i = 0; i < 12; i++) {\n        await new Promise((r) => setTimeout(r, 500))\n        if (await isMonitorOnline(config.monitorUrl)) return\n      }\n      warnOnce('anchored-monitor: 监控进程已拉起但未就绪: ' + config.monitorUrl)\n    } finally {\n      monitorBusy = false\n    }\n  }\n\n  // ── 2) 真实会话 reasoning 推送 ──\n  // 会话可读元数据: sessionId → { workspace }(来自 session/event 的 session.header.cwd)\n  const sessionMetaBySession = new Map()\n  const seqBySession = new Map()\n  const reasoningOf = (event) => {\n    const content = event && event.data && event.data.message && event.data.message.content\n    if (!Array.isArray(content)) return null\n    const parts = content\n      .filter((c) => c && (c.type === 'reasoning' || c.type === 'thinking') && typeof c.text === 'string')\n      .map((c) => c.text)\n    return parts.length > 0 ? parts.join('\\n') : null\n  }\n  const pushReasoning = async (sessionId, text) => {\n    if (!config.enabled) return\n    const seq = (seqBySession.get(sessionId) ?? 0) + 1\n    seqBySession.set(sessionId, seq)\n    const meta = sessionMetaBySession.get(sessionId)\n    if (meta && meta.subagent) return\n    try {\n      await fetch(config.monitorUrl + '/api/push', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ type: 'reasoning_block', sessionId, sequence: seq, text, timestamp: Date.now(), workspace: meta ? meta.workspace : undefined })\n      })\n    } catch {\n      // 离线时丢弃(监控进程就绪后继续); 每块最多丢一次\n    }\n  }\n  // CoT 守卫(0.2.9): 把 text 信道(可见正文)增量也推给监控进程做泄漏/停摆检测。\n  // 与 reasoning 独立的序号空间(textSeq), 不干扰推理窗口聚合。\n  const textSeqBySession = new Map()\n  const pushText = async (sessionId, text) => {\n    if (!config.enabled) return\n    const seq = (textSeqBySession.get(sessionId) ?? 0) + 1\n    textSeqBySession.set(sessionId, seq)\n    const meta = sessionMetaBySession.get(sessionId)\n    if (meta && meta.subagent) return\n    try {\n      await fetch(config.monitorUrl + '/api/push-text', {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify({ type: 'text_chunk', sessionId, sequence: seq, text, timestamp: Date.now(), workspace: meta ? meta.workspace : undefined })\n      })\n    } catch {\n      // 离线时丢弃\n    }\n  }\n  // 流式增量推送: 订阅 llm/stream 的 reasoning-delta 与 text-delta, 按 ~1s 节流分别实时推给监控进程——\n  // 图表/变阻器条在模型推理过程中就能连续跳动, 不必等整轮结束。\n  // 计数线性可加, 增量切块与整块推送在窗口聚合上完全等价。\n  const STREAM_THROTTLE_MS = 1000\n  const streamBuffers = new Map() // sessionId → { text, last, active }  (reasoning 信道)\n  const textStreamBuffers = new Map() // sessionId → { text, last, active }  (text 信道, 供 CoT 守卫)\n  ctx.on('llm/stream', (options, next) => {\n    const sessionId = options && typeof options.sessionId === 'string' ? options.sessionId : undefined\n    if (!sessionId || !config.enabled) return next()\n    const meta0 = sessionMetaBySession.get(sessionId)\n    if (meta0 && meta0.subagent) return next()\n    // 规矩(2026-08-18 事故后立下):\n    //   llm/stream 是\"流透传\"waterfall —— 链上前面的监听器会直接迭代本监听器的返回值。\n    //   ①生产方(本文件): 监听器必须是普通函数, 返回 async generator; 禁止 async 函数\n    //     (async 会把 generator 包成 Promise, 上游 for await 迭代时抛\n    //     \"next(...) is not a function or its return value is not async iterable\")。\n    //   ②消费方(所有插件): 一律 for await (const c of await next()) —— 先 await 再迭代,\n    //     下游返回 Promise 或流都能安全透传(dsh-draw-gacha 已加该防御)。\n    //   agent/pre-step、system-prompt/assemble 属\"值传递\"事件, async + await next() 是安全的。\n    return (async function* () {\n      for await (const chunk of next()) {\n        yield chunk\n        if (!chunk || typeof chunk.text !== 'string' || chunk.text === '') continue\n        if (chunk.type === 'reasoning-delta') {\n          let buf = streamBuffers.get(sessionId)\n          if (!buf) {\n            buf = { text: '', last: 0, active: true }\n            streamBuffers.set(sessionId, buf)\n          }\n          buf.text += chunk.text\n          buf.active = true\n          const now = Date.now()\n          if (now - buf.last >= STREAM_THROTTLE_MS) {\n            buf.last = now\n            const delta = buf.text\n            buf.text = ''\n            void pushReasoning(sessionId, delta)\n          }\n        } else if (chunk.type === 'text-delta') {\n          let tbuf = textStreamBuffers.get(sessionId)\n          if (!tbuf) {\n            tbuf = { text: '', last: 0, active: true }\n            textStreamBuffers.set(sessionId, tbuf)\n          }\n          tbuf.text += chunk.text\n          tbuf.active = true\n          const now = Date.now()\n          if (now - tbuf.last >= STREAM_THROTTLE_MS) {\n            tbuf.last = now\n            const delta = tbuf.text\n            tbuf.text = ''\n            void pushText(sessionId, delta)\n          }\n        }\n      }\n    })()\n  })\n  ctx.on('session/event', (session, event) => {\n    if (!session) return\n    try {\n      const ws = (session.header && session.header.cwd) ? session.header.cwd : (session.workspace || '')\n      const sub = !!(session.header && session.header.parentSession)\n      if (ws || sub) sessionMetaBySession.set(session.id, { workspace: ws, subagent: sub })\n    } catch (e) { /* 无 header 的会话忽略元数据 */ }\n    // 子代理会话不参与监控(header.parentSession 非空 = subagent, 由 dsh-subagent childSessionMeta 写入)\n    if (sessionMetaBySession.get(session.id) && sessionMetaBySession.get(session.id).subagent) return\n    if (event?.type !== 'assistant/message') return\n    // 若本轮已通过流式增量推送, 只冲掉尾部残留; 否则整段推送(适配器无 reasoning-delta 时兜底)\n    const buf = streamBuffers.get(session.id)\n    if (buf && buf.active) {\n      if (buf.text) void pushReasoning(session.id, buf.text)\n      buf.text = ''\n      buf.active = false\n      // text 信道残留也一并冲掉(CoT 守卫数据)\n      const tbuf = textStreamBuffers.get(session.id)\n      if (tbuf) {\n        if (tbuf.active && tbuf.text) void pushText(session.id, tbuf.text)\n        tbuf.text = ''\n        tbuf.active = false\n      }\n      return\n    }\n    const text = reasoningOf(event)\n    if (text) void pushReasoning(session.id, text)\n    // 无流式增量时, 正文从事件消息的 content 里取(兜底)\n    const content = event && event.data && event.data.message && event.data.message.content\n    if (Array.isArray(content)) {\n      const body = content.filter((c) => c && c.type === 'text' && typeof c.text === 'string').map((c) => c.text).join('\\n')\n      if (body) void pushText(session.id, body)\n    }\n  })\n\n  // ── 3) 干预执行(L1 提示 / L2 重置 / L3 重启建议) ──\n  const pendingHints = new Map()\n  const pendingResets = new Map()\n  const knownSessions = new Set()\n  const handledSeq = new Map()\n\n  const ackSignal = (signal, status) => {\n    const tag = 'anchored-monitor: ack L' + signal.level + ' #' + (signal.sequence ?? '?') + ' @' + signal.sessionId\n    fetch(config.monitorUrl + '/api/sessions/' + encodeURIComponent(signal.sessionId) + '/ack', {\n      method: 'POST',\n      headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ type: 'ack', sessionId: signal.sessionId, level: signal.level, status, timestamp: Date.now() })\n    })\n      .then((r) => {\n        if (!r.ok) warnOnce(tag + ' → 失败 http ' + r.status + ' (' + status + ')')\n        else if (status && String(status).indexOf('failed') === 0) warnOnce(tag + ' → 以失败态回执: ' + status)\n      })\n      .catch(() => warnOnce(tag + ' → 网络失败 (' + status + ')'))\n  }\n  /**\n   * 自动续跑: 把干预消息写入 agent inbox 并唤醒驱动(agent.followup),\n   * 新一轮请求随即开始——打断之后立即以调整后的条件继续任务, 而不是停下等用户。\n   * agents 服务不可用/无权限时回退为 pendingHints(下一轮注入, 不续跑)。\n   */\n  /** 取会话对应的 agent(agents 服务按 sessionId 索引) */\n  const agentFor = (sessionId) => {\n    try {\n      const registry = ctx.agents\n      return registry && typeof registry.get === 'function' ? registry.get(sessionId) : undefined\n    } catch {\n      return undefined\n    }\n  }\n  /**\n   * L2/L3: 强制停掉当前正在运行的回合(agent.cancel, 保留 inbox 队列),\n   * 相当于在输入框里重新注入一段上下文——软重启对话。\n   */\n  const cancelCurrentTurn = (sessionId, reason) => {\n    try {\n      const agent = agentFor(sessionId)\n      if (agent && typeof agent.cancel === 'function') {\n        agent.cancel({ kind: 'hook', reason: reason }, { keepInbox: true })\n        return true\n      }\n    } catch (err) {\n      warnOnce('anchored-monitor: 回合取消失败: ' + String(err && err.message ? err.message : err))\n    }\n    return false\n  }\n  /** 自动续跑: 把干预消息写入 agent inbox 并唤醒驱动(agent.followup) */\n  const submitContinuation = (sessionId, text) => {\n    let delivered = false\n    try {\n      const agent = agentFor(sessionId)\n      if (agent && typeof agent.followup === 'function') {\n        agent.followup({\n          role: 'user',\n          content: [{ type: 'text', text }],\n          source: { kind: 'anchored-monitor', form: 'continuation' }\n        })\n        delivered = true\n      }\n    } catch (err) {\n      warnOnce('anchored-monitor: 自动续跑失败, 回退为下一轮注入: ' + String(err && err.message ? err.message : err))\n    }\n    if (!delivered) pendingHints.set(sessionId, text)\n    return delivered\n  }\n  const executeSignal = (signal) => {\n    const label = 'anchored-monitor: L' + signal.level + ' #' + (signal.sequence ?? '?') + ' @' + signal.sessionId\n    try {\n      let delivered = false\n      let note = ''\n      if (signal.level === 'L1') {\n        delivered = submitContinuation(signal.sessionId, signal.payload && signal.payload.hintText ? signal.payload.hintText : '')\n        note = 'L1 提示'\n      } else if (signal.level === 'L2') {\n        // L2 = 软重启: ①取消当前运行中的回合(保留 inbox); ②设置重置载荷(下一轮 assemble 消费);\n        // ③followup 注入\"重新输入\"的上下文——以 Minimal persona + 双工具继续任务\n        pendingResets.set(signal.sessionId, (signal.payload && signal.payload.reset) || { systemPrompt: '', tools: [] })\n        const cancelled = cancelCurrentTurn(signal.sessionId, 'anchored-monitor L2 reset')\n        delivered = submitContinuation(signal.sessionId, 'anchored-monitor: react-band trajectory detected (' + (signal.reason || '') + '). An L2 soft-restart is applied — the running turn was stopped and this request continues under the minimal 46-character persona with the bash and str_replace_editor bootstrap pair. Continue the task from where you left off, in a plan-first collective style (we will …). 锚定监控已执行 L2 强制重置: 当前回合已停止, 本轮以 Minimal 46 字符句 + 双工具软重启, 请以规划式风格(we will / we need)从刚才的位置继续任务。')\n        note = 'L2 重置' + (cancelled ? '' : '(cancel 未命中)')\n      } else if (signal.level === 'L3') {\n        // L3 = 软重启 + 重启建议\n        pendingResets.set(signal.sessionId, (signal.payload && signal.payload.reset) || { systemPrompt: '', tools: [] })\n        const cancelled = cancelCurrentTurn(signal.sessionId, 'anchored-monitor L3 restart advice')\n        delivered = submitContinuation(signal.sessionId, 'anchored-monitor: L2 retries exhausted (' + (signal.reason || '') + '). A full session restart is recommended for the cleanest state; the running turn was stopped and the reset condition is applied — continue the task in a plan-first style. 锚定监控提示: L2 重试已耗尽, 建议全新会话; 当前回合已停止并应用重置条件, 请以规划式风格继续任务。')\n        note = 'L3 重启建议' + (cancelled ? '' : '(cancel 未命中)')\n      }\n      const status = delivered ? 'executed' : 'failed: agents.followup 不可用 (' + note + ' 已排队待注入)'\n      logInfo(label + ' → ' + (delivered ? 'executed' : status))\n      ackSignal(signal, status)\n    } catch (err) {\n      ackSignal(signal, 'failed: ' + String(err && err.message ? err.message : err))\n    }\n  }\n  // 干预执行以监控快照为唯一事实源(状态 sent=未执行): 轮询会话列表,\n  // 只对 status==='sent' 且未处理过的干预执行——监控重启/插件晚到都能自愈。\n  let pollStats = { polls: 0, lastErr: '', lastDiagAt: 0 }\n  const pollInterventions = async () => {\n    if (!config.enabled) return\n    pollStats.polls += 1\n    let summaries = []\n    try {\n      const res = await fetch(config.monitorUrl + '/api/sessions', { signal: AbortSignal.timeout(2500) })\n      if (!res.ok) { pollStats.lastErr = 'sessions http ' + res.status; return }\n      summaries = await res.json()\n    } catch (err) {\n      pollStats.lastErr = 'sessions fetch: ' + String(err && err.message ? err.message : err)\n      return\n    }\n    if (!Array.isArray(summaries)) { pollStats.lastErr = 'sessions 返回非数组'; return }\n    // 节流健康日志(30s 一次): 证明 poll 活着、能看到多少会话/待处理干预——干预不执行的现场观测锚点\n    const now = Date.now()\n    if (now - pollStats.lastDiagAt > 30000) {\n      pollStats.lastDiagAt = now\n      const pending = summaries.filter((s) => s && s.interventions > 0).length\n      logInfo('anchored-monitor: poll#' + pollStats.polls + ' ' + summaries.length + ' 会话, ' + pending + ' 会话有待处理干预, lastErr=' + (pollStats.lastErr || '无'))\n    }\n    for (const summary of summaries) {\n      const sessionId = summary.sessionId\n      if (!sessionId || !(summary.interventions > 0)) continue\n      let snapshot = null\n      try {\n        const sres = await fetch(config.monitorUrl + '/api/sessions/' + encodeURIComponent(sessionId), { signal: AbortSignal.timeout(2500) })\n        if (!sres.ok) continue\n        snapshot = await sres.json()\n      } catch (err) {\n        pollStats.lastErr = 'snapshot fetch @' + sessionId + ': ' + String(err && err.message ? err.message : err)\n        continue\n      }\n      const list = snapshot && snapshot.interventions ? snapshot.interventions : []\n      for (const iv of list) {\n        if (iv.status !== 'sent') continue\n        if (iv.sequence <= (handledSeq.get(sessionId) ?? 0)) continue\n        handledSeq.set(sessionId, iv.sequence)\n        try {\n          executeSignal(iv)\n        } catch (err) {\n          // 单条干预异常不阻断后续轮询\n          warnOnce('anchored-monitor: 干预执行异常 @' + sessionId + ' #' + iv.sequence + ': ' + String(err && err.message ? err.message : err))\n        }\n      }\n    }\n  }\n\n  // L1/L3: 提示注入(instruction-hint 注入模式; 必须调用 next())\n  ctx.on('agent/pre-step', async ({ agent, signal }, next) => {\n    const decision = await next()\n    try {\n      const session = agent && agent.session\n      if (!session) return decision\n      const hint = pendingHints.get(session.id)\n      if (hint === undefined) return decision\n      pendingHints.delete(session.id)\n      return {\n        ...decision,\n        messages: [...(decision.messages ?? []), {\n          id: 'anchored-monitor-hint-' + session.id,\n          role: 'user',\n          content: [{ type: 'text', text: hint }],\n          source: { kind: 'anchored-monitor', form: 'hint' }\n        }]\n      }\n    } catch (err) {\n      warnOnce('anchored-monitor: 提示注入失败: ' + String(err && err.message ? err.message : err))\n      return decision\n    }\n  }, { prepend: true })\n\n  // L2: persona 段替换 + 工具目录收缩(router-core.applyPersona + tool-bootstrap 模式)\n  ctx.on('system-prompt/assemble', async (_assembly, context, next) => {\n    const assembled = await next()\n    try {\n      const session = context && context.agent && context.agent.session\n      if (!session) return assembled\n      const reset = pendingResets.get(session.id)\n      if (!reset) return assembled\n      pendingResets.delete(session.id)\n      const sections = (assembled.sections ?? []).filter((s) => s.name !== 'persona' && !/persona/i.test(s.name))\n      sections.push({ name: 'anchored-monitor-persona', text: reset.systemPrompt ?? '', order: 0 })\n      const keep = new Set(reset.tools ?? [])\n      const tools = Array.isArray(assembled.tools) ? assembled.tools.filter((t) => keep.has(t.name)) : assembled.tools\n      return { ...assembled, sections, tools }\n    } catch (err) {\n      // 过滤失败退化为完整目录, 绝不 brick 会话\n      warnOnce('anchored-monitor: 重置注入失败: ' + String(err && err.message ? err.message : err))\n      return assembled\n    }\n  })\n\n  // ── 4) 路由 + 生命周期 ──\n  ctx.effect(() => {\n    void (async () => {\n      await reload()\n      void ensureMonitorRunning()\n    })()\n    const watchdog = setInterval(() => void ensureMonitorRunning(), 15000)\n    const pollTimer = setInterval(() => void pollInterventions(), 1500)\n\n    const disposers = []\n    const guard = (req, res) => {\n      if (!isLoopbackRequest(req)) {\n        writeJson(res, 403, { error: 'forbidden: loopback-only' })\n        return false\n      }\n      return true\n    }\n    const routes = [\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/update-check',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          const now = Date.now()\n          if (updateCache && now - updateCache.at < UPDATE_TTL_MS) {\n            return writeJson(res, 200, { ok: true, ...updateCache })\n          }\n          try {\n            const localRaw = await readFile(path.join(PACKAGE_ROOT, 'package.json'), 'utf8')\n            const current = String(JSON.parse(localRaw).version || '0.0.0')\n            let latest = current\n            try {\n              const remote = await fetch(UPDATE_RAW_URL, { signal: AbortSignal.timeout(6000) })\n              if (remote.ok) latest = String(JSON.parse(await remote.text()).version || current)\n            } catch (e) {\n              warnOnce('anchored-monitor: 更新检查上游不可达: ' + String(e && e.message ? e.message : e))\n            }\n            const hasUpdate = semverGt(latest, current)\n            updateCache = { at: now, current: current, latest: latest, hasUpdate: hasUpdate }\n            return writeJson(res, 200, {\n              ok: true,\n              current: current,\n              latest: latest,\n              hasUpdate: hasUpdate,\n              releaseUrl: 'https://github.com/Aik358/dsh-anchored-monitor/releases/tag/v' + latest,\n              npmUrl: 'https://www.npmjs.com/package/@a9i5k4/dsh-anchored-monitor'\n            })\n          } catch (err) {\n            return writeJson(res, 200, { ok: false, error: 'update-check failed: ' + String(err && err.message ? err.message : err) })\n          }\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/status',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          await reload()\n          const online = await isMonitorOnline(config.monitorUrl)\n          let version = null\n          if (online) {\n            try {\n              version = (await (await fetch(config.monitorUrl + '/api/health', { signal: AbortSignal.timeout(1500) })).json()).version ?? null\n            } catch {\n              // 忽略\n            }\n          }\n          writeJson(res, 200, { ok: true, enabled: config.enabled, autoStart: config.autoStart, monitorUrl: config.monitorUrl, profile: config.profile, monitorOnline: online, version })\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/config',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if (req.method === 'GET') {\n            await reload()\n            return writeJson(res, 200, { ok: true, ...config })\n          }\n          if (req.method === 'POST') {\n            const payload = await readJsonBody(req)\n            if (!payload || typeof payload !== 'object') return writeJson(res, 400, { ok: false, error: 'invalid JSON body' })\n            const next = { ...config }\n            if (typeof payload.monitorUrl === 'string' && /^https?:\\/\\//.test(payload.monitorUrl)) next.monitorUrl = payload.monitorUrl\n            if (typeof payload.enabled === 'boolean') next.enabled = payload.enabled\n            if (typeof payload.autoStart === 'boolean') next.autoStart = payload.autoStart\n            if (typeof payload.profile === 'string' && payload.profile !== '') next.profile = payload.profile\n            if (payload.monitorOverrides && typeof payload.monitorOverrides === 'object') next.monitorOverrides = payload.monitorOverrides\n            try {\n              await mkdir(homeFile(), { recursive: true })\n              await writeFile(configPath(), JSON.stringify(next, null, 2), 'utf8')\n            } catch (err) {\n              return writeJson(res, 500, { ok: false, error: 'config write failed: ' + String(err && err.message ? err.message : err) })\n            }\n            config = next\n            return writeJson(res, 200, { ok: true, ...config })\n          }\n          return writeJson(res, 405, { ok: false, error: 'method not allowed' })\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/settings',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if (req.method === 'GET') {\n            await reload()\n            const online = await isMonitorOnline(config.monitorUrl)\n            let effective = null\n            if (online) {\n              try {\n                effective = await (await fetch(config.monitorUrl + '/api/config', { signal: AbortSignal.timeout(2000) })).json()\n              } catch {\n                effective = null\n              }\n            }\n            return writeJson(res, 200, { ok: true, host: config, monitorOnline: online, effective })\n          }\n          if (req.method === 'POST') {\n            const payload = await readJsonBody(req)\n            if (!payload || typeof payload !== 'object') return writeJson(res, 400, { ok: false, error: 'invalid JSON body' })\n            const next = { ...config }\n            const hostPatch = payload.host\n            if (hostPatch && typeof hostPatch === 'object') {\n              if (typeof hostPatch.monitorUrl === 'string' && /^https?:\\/\\//.test(hostPatch.monitorUrl)) next.monitorUrl = hostPatch.monitorUrl\n              if (typeof hostPatch.enabled === 'boolean') next.enabled = hostPatch.enabled\n              if (typeof hostPatch.autoStart === 'boolean') next.autoStart = hostPatch.autoStart\n              if (typeof hostPatch.profile === 'string' && hostPatch.profile !== '') next.profile = hostPatch.profile\n            }\n            const overridesPatch = payload.overrides\n            if (payload.reset === true) {\n              // 一键还原默认: 清空全部 overrides, 监控回该 profile 的出厂参数(不动 profile/monitorUrl/enabled)\n              next.monitorOverrides = {}\n            } else if (overridesPatch && typeof overridesPatch === 'object') {\n              next.monitorOverrides = { ...next.monitorOverrides, ...overridesPatch }\n            }\n            // 端口联动: overrides.dashboard.port 变更时同步 monitorUrl\n            const port = next.monitorOverrides.dashboard && next.monitorOverrides.dashboard.port\n            if (typeof port === 'number' && port > 0) {\n              next.monitorUrl = 'http://127.0.0.1:' + port\n            }\n            try {\n              await mkdir(homeFile(), { recursive: true })\n              await writeFile(configPath(), JSON.stringify(next, null, 2), 'utf8')\n              await writeFile(overridesPath(), JSON.stringify(next.monitorOverrides ?? {}, null, 2), 'utf8')\n            } catch (err) {\n              return writeJson(res, 500, { ok: false, error: 'config write failed: ' + String(err && err.message ? err.message : err) })\n            }\n            config = next\n            // 重启监控进程使新参数生效\n            let restarted = false\n            try {\n              await fetch(config.monitorUrl + '/api/shutdown', { method: 'POST', signal: AbortSignal.timeout(1500) })\n              restarted = true\n            } catch {\n              // 本来就没在线\n            }\n            await new Promise((r) => setTimeout(r, 700))\n            await ensureMonitorRunning()\n            const online = await isMonitorOnline(config.monitorUrl)\n            return writeJson(res, 200, { ok: true, saved: true, restarted, monitorOnline: online, host: config })\n          }\n          return writeJson(res, 405, { ok: false, error: 'method not allowed' })\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/intervention',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if (req.method === 'GET') {\n            try {\n              const upstream = await fetch(config.monitorUrl + '/api/intervention', { signal: AbortSignal.timeout(2000) })\n              const body = await upstream.text()\n              res.writeHead(upstream.status, { 'content-type': 'application/json; charset=utf-8' })\n              res.end(body)\n            } catch {\n              writeJson(res, 502, { ok: false, monitorOnline: false, error: 'monitor-offline' })\n            }\n            return\n          }\n          if (req.method === 'POST') {\n            const payload = await readJsonBody(req)\n            if (!payload || typeof payload.enabled !== 'boolean') return writeJson(res, 400, { ok: false, error: '需要 { enabled: boolean }' })\n            let forwarded = false\n            try {\n              const upstream = await fetch(config.monitorUrl + '/api/intervention', {\n                method: 'POST',\n                headers: { 'content-type': 'application/json' },\n                body: JSON.stringify({ enabled: payload.enabled }),\n                signal: AbortSignal.timeout(2000)\n              })\n              const body = await upstream.text()\n              forwarded = upstream.ok\n              res.writeHead(upstream.status, { 'content-type': 'application/json; charset=utf-8' })\n              res.end(body)\n            } catch {\n              writeJson(res, 502, { ok: false, monitorOnline: false, error: 'monitor-offline' })\n              return\n            }\n            if (forwarded) {\n              // 持久化: 下次监控进程启动沿用\n              try {\n                await reload()\n                const nextOverrides = { ...config.monitorOverrides }\n                if (!nextOverrides.intervention || typeof nextOverrides.intervention !== 'object') nextOverrides.intervention = {}\n                nextOverrides.intervention.enabled = payload.enabled\n                const next = { ...config, monitorOverrides: nextOverrides }\n                await mkdir(homeFile(), { recursive: true })\n                await writeFile(configPath(), JSON.stringify(next, null, 2), 'utf8')\n                await writeFile(overridesPath(), JSON.stringify(nextOverrides, null, 2), 'utf8')\n                config = next\n              } catch (err) {\n                warnOnce('anchored-monitor: 干预开关持久化失败: ' + String(err && err.message ? err.message : err))\n              }\n            }\n            return\n          }\n          return writeJson(res, 405, { ok: false, error: 'method not allowed' })\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/overview',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          if (!config.enabled) return writeJson(res, 200, { ok: false, enabled: false, monitorOnline: false, error: 'plugin-disabled' })\n          return proxyGet(config.monitorUrl, req, res, '/api/overview')\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/sessions',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          if (!config.enabled) return writeJson(res, 200, { ok: false, enabled: false, error: 'plugin-disabled' })\n          return proxyGet(config.monitorUrl, req, res, '/api/sessions')\n        }\n      },\n      {\n        kind: 'exact',\n        path: API_PREFIX + '/events',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          if (!config.enabled) return writeJson(res, 200, { ok: false, enabled: false, error: 'plugin-disabled' })\n          return proxyGet(config.monitorUrl, req, res, '/api/events')\n        }\n      },\n      {\n        kind: 'prefix',\n        path: API_PREFIX + '/sessions/',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          if (!config.enabled) return writeJson(res, 200, { ok: false, enabled: false, error: 'plugin-disabled' })\n          const pathname = new URL(req.url || '/', 'http://localhost').pathname\n          return proxyGet(config.monitorUrl, req, res, pathname.slice(API_PREFIX.length))\n        }\n      },\n      {\n        kind: 'prefix',\n        path: API_PREFIX + '/assets/',\n        handler: async (req, res) => {\n          if (!guard(req, res)) return\n          if ((req.method || 'GET') !== 'GET') return writeJson(res, 405, { error: 'method not allowed' })\n          // 皮肤素材(assets/liang/liang-0..5.png): basename 白名单, 杜绝路径穿越。\n          const pathname2 = new URL(req.url || '/', 'http://localhost').pathname\n          const name = path.basename(pathname2)\n          if (!/^liang-\\d+\\.png$/.test(name)) return writeJson(res, 404, { ok: false, error: 'not-found' })\n          const file = path.join(PACKAGE_ROOT, 'assets', 'liang', name)\n          try {\n            const buf = await readFile(file)\n            res.writeHead(200, {\n              'content-type': 'image/png',\n              'content-length': buf.length,\n              'cache-control': 'public, max-age=3600'\n            })\n            res.end(buf)\n          } catch {\n            writeJson(res, 404, { ok: false, error: 'not-found' })\n          }\n        }\n      }\n    ]\n    for (const route of routes) disposers.push(ctx.webServer.register(route))\n    disposers.push(ctx.systemPrompt.section({ name: 'plugin:anchored-monitor', order: SECTION_ORDER, text: GUIDANCE }))\n    return () => {\n      clearInterval(watchdog)\n      clearInterval(pollTimer)\n      for (const dispose of disposers) {\n        try {\n          dispose()\n        } catch {\n          // 卸载失败不阻塞\n        }\n      }\n      if (monitorProc) {\n        try {\n          monitorProc.kill()\n        } catch {\n          // 已退出\n        }\n        monitorProc = null\n      }\n    }\n  }, 'dsh-anchored-monitor: host monitor lifecycle + proxy + interventions')\n}\n"
